const movimientos = $input.all();
let ingresosLanus = 0;
let egresosLanus = 0;
let ingresosBelgrano = 0;
let egresosBelgrano = 0;

movimientos.forEach(item => {
  const m = item.json;
  const monto = parseFloat(m.monto || 0);
  const sucursal = (m.sucursal || '').toLowerCase();
  const tipo = (m.tipo || '').toLowerCase();

  if (sucursal.includes('lanus')) {
    if (tipo === 'ingreso') ingresosLanus += monto;
    else if (tipo === 'egreso') egresosLanus += monto;
  } else if (sucursal.includes('belgrano')) {
    if (tipo === 'ingreso') ingresosBelgrano += monto;
    else if (tipo === 'egreso') egresosBelgrano += monto;
  }
});

const gananciaLanus = ingresosLanus - egresosLanus;
const gananciaBelgrano = ingresosBelgrano - egresosBelgrano;
const totalIngresos = ingresosLanus + ingresosBelgrano;
const totalEgresos = egresosLanus + egresosBelgrano;
const gananciaNetaTotal = totalIngresos - totalEgresos;

return [{
  json: {
    fecha: new Date().toLocaleDateString('es-AR'),
    lanus: { ingresos: ingresosLanus, egresos: egresosLanus, neto: gananciaLanus },
    belgrano: { ingresos: ingresosBelgrano, egresos: egresosBelgrano, neto: gananciaBelgrano },
    global: { ingresos: totalIngresos, egresos: totalEgresos, neto: gananciaNetaTotal }
  }
}];

